The issue is a **unit mismatch**:

* **`Date.now()`** returns the current timestamp in **milliseconds**.
* **JWT `exp` claim** (per RFC 7519) is stored in **seconds**.

Because of this, `Date.now()` is ~1,000 times larger than `exp`. Depending on how your comparison was structured, the logic breaks completely.

---

### Option 1: Fix the manual comparison

Convert `Date.now()` to seconds (or `exp` to milliseconds):

```javascript
// Convert Date.now() to seconds:
const isExpired = token.exp < Math.floor(Date.now() / 1000);

if (isExpired) {
  return res.status(401).json({ message: 'Token has expired' });
}
```

---

### Option 2: The Recommended Way (Use `jwt.verify`)

If you are manually decoding the token (e.g., using `jwt.decode()` or `JSON.parse(atob(...))`), **your app is vulnerable to token tampering** because manual checks do not verify the cryptographic signature.

Use `jsonwebtoken`’s `jwt.verify()` method instead. It automatically validates both the **signature** and the **expiration time (`exp`)**:

```javascript
const jwt = require('jsonwebtoken');

function authMiddleware(req, res, next) {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ message: 'No token provided' });
  }

  const token = authHeader.split(' ')[1];

  try {
    // jwt.verify automatically checks 'exp' against Date.now()
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (err) {
    if (err.name === 'TokenExpiredError') {
      return res.status(401).json({ message: 'Token has expired' });
    }
    return res.status(403).json({ message: 'Invalid token' });
  }
}

module.exports = authMiddleware;
```

