Use `pg` library (`npm i pg`).

### Setup & Config

```javascript
const { Pool } = require('pg');

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,                          // max active connections
  idleTimeoutMillis: 30000,         // close idle client after 30s
  connectionTimeoutMillis: 2000,    // fail fast if pool full / db down (2s)
  statement_timeout: 5000           // cancel query if running > 5s
});

// Catch errors on idle clients (critical: prevents process crash)
pool.on('error', (err, client) => {
  console.error('Unexpected idle client error', err);
});
```

### Usage Pattern

```javascript
// Single query via pool root (auto checkout & release)
async function query(text, params) {
  try {
    return await pool.query(text, params);
  } catch (err) {
    console.error('Query error:', err.message);
    throw err;
  }
}

// Transaction (manual checkout, must release in finally)
async function executeTx(callback) {
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const res = await callback(client);
    await client.query('COMMIT');
    return res;
  } catch (err) {
    await client.query('ROLLBACK');
    throw err;
  } finally {
    client.release(); // Avoid connection leak
  }
}
```

### Key Flags
- `connectionTimeoutMillis`: stops thread lock when pool exhausted.
- `pool.on('error')`: prevents backend crash on network drop.
- `client.release()`: always put in `finally`.

