Here are the standard ways to refactor this depending on whether your database library supports Promises natively or is callback-only.

---

### Option 1: If your DB library supports Promises (Modern / Recommended)
*(e.g., `mysql2/promise`, `pg`, `sqlite3`, etc.)*

```javascript
async function getUser(id) {
  const rows = await db.query('SELECT * FROM users WHERE id = ?', [id]);

  if (!rows.length) {
    throw new Error('Not found');
  }

  return rows[0];
}
```

> **Note for `mysql2/promise` users:** If using `mysql2/promise`, `query` returns `[rows, fields]`, so destructure it like `const [rows] = await db.query(...)`.

---

### Option 2: If `db.query` only supports callbacks
If your DB client does not return a Promise, you can wrap it manually using a `Promise`:

```javascript
async function getUser(id) {
  return new Promise((resolve, reject) => {
    db.query('SELECT * FROM users WHERE id = ?', [id], (err, rows) => {
      if (err) return reject(err);
      if (!rows.length) return reject(new Error('Not found'));
      resolve(rows[0]);
    });
  });
}
```

Alternatively, you can use Node.js's built-in `util.promisify`:

```javascript
const util = require('util');
const query = util.promisify(db.query).bind(db);

async function getUser(id) {
  const rows = await query('SELECT * FROM users WHERE id = ?', [id]);

  if (!rows.length) {
    throw new Error('Not found');
  }

  return rows[0];
}
```

---

### How to use the refactored function:

```javascript
async function main() {
  try {
    const user = await getUser(1);
    console.log('User found:', user);
  } catch (err) {
    console.error('Error fetching user:', err.message);
  }
}
```

